    out = {}

    def go(i):
        if i == 0:
            out[i] = call("GET", "/_test/export")
        else:
            out[i] = call("POST", "/payments", {"to_handle": f"b{(i + 3) % 10}", "amount": 37}, token=tokens[i % 10], key=f"k{attempt}-{i}")

    threads = [threading.Thread(target=go, args=(i,)) for i in range(50)]
    for t in threads[1:25]:
        t.start()
    threads[0].start()
    for t in threads[25:]:
        t.start()
    for t in threads:
        t.join()
    st = json.loads(out[0][1])["state"]
    bal = {u["id"]: u["balance"] for u in st["users"]}
    recon = {u["id"]: 1000 for u in st["users"]}
    for p in st["payments"]:
        recon[p["from_user_id"]] -= p["amount"]
        recon[p["to_user_id"]] += p["amount"]
    bad = {k: (bal[k], recon[k]) for k in bal if bal[k] != recon[k]}
    ok = sum(1 for i in range(1, 50) if out[i][0] == 201)
    print(f"attempt {attempt}: {ok} payments 201; exported payments {len(st['payments'])}, idempotency records {len(st['idempotency'])}; "
