{"args":{"content":"#!/usr/bin/env bash
# Builder gate for the UI items at one commit: offline build and page probe, acceptance suite,
# supplied checks. Usage: gate-ui.sh <worktree> <suite-worktree> <upto> <harness-out-name>
set -uo pipefail
WT="$1"; SUITE="$2"; UPTO="$3"; OUT="$4"
LOGS=/Users/Dileepa/dark-factory-v3/.work/builder-h6bg
NAME=pf-builder-s2

echo "== offline build"
docker rm -f "$NAME" >/dev/null 2>&1
docker build --network=none -q -t "$NAME" "$WT/stage-2" >/dev/null; echo "build exit $?"
docker run -d --network=none --name "$NAME" "$NAME" >/dev/null; echo "run exit $?"
for _ in $(seq 1 60); do docker exec "$NAME" node -e "fetch('http://127.0.0.1:8080/health').then(r=>process.exit(r.ok?0:1),()=>process.exit(1))" 2>/dev/null && break; sleep 0.5; done
docker exec "$NAME" node -e '
const B = "http://127.0.0.1:8080";
const html = { accept: "text/html,application/xhtml+xml;q=0.9,*/*;q=0.8" };
const probes = [["/health", {}], ["/", {}], ["/login", {}], ["/signup", {}], ["/split", {}],
  ["/requests", html], ["/authorizations", html], ["/requests", {}], ["/nowhere", html], ["/nowhere", {}]];
const out = [];
for (const [p, h] of probes) {
  const r = await fetch(B + p, { headers: h });
  const t = await r.text();
  out.push(`${p} ${h.accept ? "(html)" : ""} ${r.status} ${r.headers.get("content-type")} csp=${r.headers.has("content-security-policy")} ${t.slice(0, 40).replace(/\s+/g, " ")}`);
}
const shell = await (await fetch(B + "/")).text();
const refs = [...shell.matchAll(/(?:href|src)="([^"]+)"/g)].map((m) => m[1]).filter((u) => u.startsWith("/"));
const seen = new Set(refs);
const queue = [...refs];
while (queue.length) {
  const u = queue.shift();
  const r = await fetch(B + u);
  const t = await r.text();
  out.push(`${u} ${r.status} ${r.headers.get("content-type")} nosniff=${r.headers.get("x-content-type-options")}`);
  if (/https?:\/\/(?!www\.w3\.org)/.test(t)) out.push(`  ${u} names another origin`);
  for (const m of t.matchAll(/from\s+["\x27](\.\/[^"\x27]+)["\x27]|import\(["\x27](\.\/[^"\x27]+)["\x27]\)/g)) {
    const next = "/assets/" + (m[1] || m[2]).slice(2);
    if (!seen.has(next)) { seen.add(next); queue.push(next); }
  }
}
console.log(out.join("\n"));
console.log(`assets fetched: ${seen.size}`);
'
echo "probe exit $?"
docker rm -f "$NAME" >/dev/null 2>&1

echo "== acceptance --upto $UPTO"
"$SUITE/stage-2/acceptance/run.sh" --upto "$UPTO" --name pf-builder-acc --port 18101 --stage-dir "$WT/stage-2" \
  --shots "$LOGS/shots-$(git -C "$WT" rev-parse --short HEAD)" > "$LOGS/acc-$OUT.log" 2>&1
echo "acceptance exit $?"; tail -3 "$LOGS/acc-$OUT.log"

echo "== harness"
rm -rf "/Users/Dileepa/dark-factory-v3/.work/checks/$OUT"
/Users/Dileepa/dark-factory-v3/scripts/harness.sh run --track pocketful --repo "$WT" --stage 2 \
  --out "/Users/Dileepa/dark-factory-v3/.work/checks/$OUT" > "$LOGS/$OUT.log" 2>&1
