effective_at proves the service accepted an effective_at later than the operation's now (a tolerance)."""
import json
import sys
import urllib.request
import uuid
from datetime import datetime, timedelta, timezone

base = sys.argv[1]


def call(method, path, body=None, token=None, key=None):
    headers = {"Content-Type": "application/json"}
    if token:
        headers["Authorization"] = "Bearer " + token
    if key is not None:
        headers["Idempotency-Key"] = key
    req = urllib.request.Request(base + path, method=method, headers=headers,
                                 data=None if body is None else json.dumps(body).encode())
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            raw = r.read()
            return r.status, json.loads(raw) if raw else None
    except urllib.error.HTTPError as e:
        raw = e.read()
        return e.code, json.loads(raw) if raw else None


def user(h, balance):
    return {"id": f"u_{h}", "email": f"{h}@example.com", "password": "correct horse", "display_name": h.title(),
            "handle": h, "balance": balance}


def parse(ts):
    return datetime.fromisoformat(ts.replace("Z", "+00:00"))


def fmt(dt):
    return dt.astimezone(timezone.utc).isoformat(timespec="microseconds").replace("+00:00", "Z")


assert call("POST", "/_test/reset", {"currency": "EUR", "minor_units": 2,
                                     "users": [user("ada", 10000), user("bob", 0)]})[0] == 204
ada = call("POST", "/auth/login", {"email": "ada@example.com", "password": "correct horse"})[1]["token"]
st, p = call("POST", "/payments", {"to_handle": "bob", "amount": 100}, ada, str(uuid.uuid4()))
assert st == 201, (st, p)
fails = 0
for ahead_ms in (300, 200, 100):
    st, mark = call("POST", "/requests", {"payer_handle": "bob", "amount": 1, "note": "time mark"}, ada, str(uuid.uuid4()))
    assert st == 201, (st, mark)
    eff = fmt(parse(mark["created_at"]) + timedelta(milliseconds=ahead_ms))
    st, body = call("POST", f"/payments/{p['payment_id']}/corrections",
                    {"expected_revision": 1, "amount": 100, "effective_at": eff, "reason": "probe"}, ada, str(uuid.uuid4()))
    if st == 422:
        print(f"PASS effective_at {ahead_ms} ms after the newest timestamp is 422")
        continue
    late = st == 201 and parse(body["recorded_at"]) < parse(eff)
    print(("FAIL" if late else "INCONCLUSIVE") + f" effective_at {ahead_ms} ms after the newest timestamp: {st} {body}")
    fails += late
    break
sys.exit(1 if fails else 0)
